import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    matrix = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(iterator)))
        matrix.append(row)

    current_n = n
